/bin/bash -lc "DATABASE_PATH=/tmp/job-tracker-recovery-review.db node --input-type=module <<'EOF'
import { openDatabase } from './dist/db.js';
const db = openDatabase();
db.prepare("'`INSERT OR REPLACE INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,result,error,created_at,updated_at,retry_at)
VALUES('"'recover-test','running','hello',1,3,3,0,NULL,NULL,?,?,0)"'`).run(new Date().toISOString(),new Date().toISOString());
db.close();
EOF
DATABASE_PATH=/tmp/job-tracker-recovery-review.db node --disable-warning=ExperimentalWarning dist/worker.js & worker_pid=$!; sleep 0.4; kill -TERM "$worker_pid" 2>/dev/null || true; wait "$worker_pid" 2>/dev/null || true
DATABASE_PATH=/tmp/job-tracker-recovery-review.db node --input-type=module -e "import {openDatabase} from '"'./dist/db.js'; const db=openDatabase(); console.log(db.prepare(\\\"SELECT status,attempts,error,result FROM jobs WHERE id='recover-test'\\\").get()); db.close();\""

